{{harvnb |Pappe |2022 |p=127 |ps=, "Two hundred men between the ages of thirteen and thirty were massacred"}};
{{harvnb |Khoury |2012 |p=263}};
{{harvnb |Masalha |2012 |p=85 |ps=, "between 70 and 200 Palestinian civilians were killed ... in a large-scale, well-planned massacre"}};
{{harvnb |Lentin |2010 |pp=69–71, 140}};
